# -*- coding: utf-8 -*-
import logging

from taf.fdsw.rc.interfaces.FDSW21D.autoconnection import AutoConfiguration21D
from taf.fdsw.rc.schemas.FDSW22A.autoconnection import (AutoConnection22A,
                                                        Site_Identification22A)
from taf.fdsw.rc.schemas.FDSW22A.autoconnection_parameters_builder_22a import \
    AutoconnectionParametersBuilder22A
from taf.fdsw.rc.schemas.FDSW22A.gnss import GNSS22A

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class AutoConfiguration22A(AutoConfiguration21D):
    param_builder = AutoconnectionParametersBuilder22A

    def __init__(self, client):
        super(AutoConfiguration22A, self).__init__(client)

    def get_site_identification_info(self, timeout=10):
        get_site_identification_info = self._client.send(
            method='config.identification.fetch',
            timeout=timeout,
            parameters={})
        get_site_identification_info = Site_Identification22A.from_object_dict(data=get_site_identification_info.data)
        return get_site_identification_info.to_dict()

    def get_site_identification_siteId(self, timeout=10):
        site_info = self.get_site_identification_info()
        return site_info['siteId']

    def get_autoconnection_parameters(self, timeout=10):
        autoconnection = self.autoconnection_parameters()
        autoconnection_parameters = AutoConnection22A.from_object_dict(data=autoconnection.data)
        return autoconnection_parameters.to_dict()

    def enable_gnss_constellations(self, constellations, timeout=10):
        constellations = [item.upper() for item in constellations]
        set_site_identification_response = self._client.send(
            method='config.gnss.update',
            timeout=timeout,
            parameters={
                'gnss': {
                    'constellationsEnabled': constellations,
                }})
        return set_site_identification_response.data

    def get_gnss(self, timeout):
        gnss_info = self._client.send(
            method='config.gnss.fetch',
            timeout=timeout,
            parameters={})
        gnss_info = GNSS22A.from_object_dict(data=gnss_info.data)
        return gnss_info.gnss.to_dict()

    def get_supported_gnss_constellations(self, timeout=10):
        return self.get_gnss(timeout)['constellations_supported']

    def get_gnss_constellations_status(self, timeout=10):
        return self.get_gnss(timeout)['status']
